WITH prev_events AS (SELECT *, LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) AS prev_txn_time FROM transactions), flagged AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_session FROM prev_events), sessions_transactions AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT DATE_TRUNC('QUARTER', txn_time) AS quarter_start, DATE_TRUNC('YEAR', prev_txn_time) AS year_start, AVG(amount) AS avg_amount, AVG(is_new_session) AS avg_is_new_session, AVG(amount) AS avg_amount_2 FROM sessions_transactions GROUP BY quarter_start, year_start
